package com.shengyu.module.platform.api.tenant;import com.shengyu.framework.common.util.object.BeanUtils;import com.shengyu.module.platform.api.tenant.dto.menu.TenantMenuListReqDTO;import com.shengyu.module.platform.api.tenant.dto.menu.TenantMenuRespDTO;import com.shengyu.module.platform.controller.platform.tenant.vo.menu.TenantMenuListReqVO;import com.shengyu.module.platform.service.tenant.TenantMenuService;import java.util.List;import javax.annotation.Resource;import org.springframework.stereotype.Service;/** * @author zhusy * @since 2022/8/6 */@Servicepublic class TenantMenuApiImpl implements TenantMenuApi {    @Resource    private TenantMenuService tenantMenuService;    @Override    public List<TenantMenuRespDTO> getTenantMenuList(TenantMenuListReqDTO reqDTO) {        TenantMenuListReqVO reqVO = BeanUtils.toBean(reqDTO, TenantMenuListReqVO.class);        return BeanUtils.toBean(tenantMenuService.getMenuList(reqVO), TenantMenuRespDTO.class);    }    @Override    public List<Long> getMenuIdListByPermissionFromCache(String permission) {        return tenantMenuService.getMenuIdListByPermissionFromCache(permission);    }}